INSERT INTO dump_descriptions (base_key, description) VALUES ('shieldlinkrange-0.1.0', 'Draws a ring around dwarves to show their Shield Link radius, updating its size from LinkDistance and hiding it while the terrain scanner is raised. The Mod Hub page provides visibility and display-mode settings.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
